import numpy as np

v0, gamma, rho_max = 1.34, 1.913, 5.4
def speed(rho):
    return v0 * (1 - np.exp(-gamma * (1 / rho - 1 / rho_max)))

rho = np.arange(0.1, 5.4, 0.01)
flow = rho * speed(rho)
i = flow.argmax()
print(f'capacity {flow[i]:.2f} per m per s at {rho[i]:.2f} per m2, speed {speed(rho[i]):.2f} m/s')
for r in [0.5, 1, 2, 3, 4]:
    print(f'rho {r}: v {speed(r):.2f} m/s, J {r*speed(r):.2f} per m per s')
